import{_ as t}from"./chunks/hiwonder_mecanum.CiOwITfD.js";import{_ as a}from"./chunks/hiwonder_wiring_annotated.BQltOWsO.js";import{_ as i}from"./chunks/hiwonder_mecanum_motors.CNVP1VmR.js";import{_ as n,C as s,o as l,c as h,j as r,a as c,E as d,al as p}from"./chunks/framework.7vp1BMOE.js";const S=JSON.parse('{"title":"Hiwonder Mecanum","description":"","frontmatter":{},"headers":[],"relativePath":"en/complete_vehicles_rover/hiwonder_mecanum.md","filePath":"en/complete_vehicles_rover/hiwonder_mecanum.md"}'),m={name:"en/complete_vehicles_rover/hiwonder_mecanum.md"};function u(f,e,g,w,v,b){const o=s("Badge");return l(),h("div",null,[e[0]||(e[0]=r("h1",{id:"hiwonder-mecanum",tabindex:"-1"},[c("Hiwonder Mecanum "),r("a",{class:"header-anchor",href:"#hiwonder-mecanum","aria-label":'Permalink to "Hiwonder Mecanum"'},"​")],-1)),d(o,{type:"tip",text:"PX4 v1.18"}),e[1]||(e[1]=p('<p>The <a href="https://www.hiwonder.com/products/large-metal-4wd-vehicle-chassis-green" target="_blank" rel="noreferrer">Hiwonder Mecanum</a> rover is a bare-bones platform including a chassis, four <a href="https://www.hiwonder.com/products/97mm-mecanum-wheel" target="_blank" rel="noreferrer">mecanum wheels</a>, four <a href="https://www.hiwonder.com/products/hall-encoder-dc-geared-motor?variant=40451123675223" target="_blank" rel="noreferrer">motors with encoders</a> and a <a href="https://www.hiwonder.com/products/4-channel-encoder-motor-driver" target="_blank" rel="noreferrer">motor driver board</a>. The chassis offers many mounting points, providing the flexibility to attach your own flight controller, sensors and other payload.</p><p>This documentation illustrates the setup of the rover and the configuration of the actuators.</p><p><img src="'+t+'" alt="Hiwonder Mecanum"></p><h2 id="parts-list" tabindex="-1">Parts List <a class="header-anchor" href="#parts-list" aria-label="Permalink to &quot;Parts List&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The hardware below is just an example — use whatever you have available. Make sure all parts are compatible with your flight controller&#39;s ports, and adjust the wiring as needed. Alternatives are listed in:</p><ul><li><a href="./../flight_controller/">Flight Controllers</a></li><li><a href="./../getting_started/rc_transmitter_receiver#compatible_receivers">PX4-Compatible Receivers</a></li><li><a href="./../data_links/">Data Links</a></li><li><a href="./../gps_compass/#supported-gnss">Global Navigation Satellite Systems (GNSS)</a> or <a href="./../gps_compass/rtk_gps">RTK GNSS</a></li></ul></div><p>The following parts are used in this build:</p><ul><li><p>Frame: <a href="https://www.hiwonder.com/products/large-metal-4wd-vehicle-chassis-green" target="_blank" rel="noreferrer">Hiwonder Mecanum Chassis</a></p></li><li><p>Flight Controller: <a href="https://auterion.com/product/skynode-s/" target="_blank" rel="noreferrer">Auterion Skynode S</a></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The flight controller and motor driver board used in this build are both directly supplied at the same 3S battery voltage (~11V).</p><p>Many flight controllers require a lower voltage power supply, so if you are using a different controller you may need a DC-to-DC converter to power it from the battery — see <a href="./../power_module/">Power Modules &amp; Power Distribution Boards</a>.</p></div></li><li><p>Receiver: <a href="https://www.team-blacksheep.com/products/prod:crossfire_nano_rx?srsltid=AfmBOopvPF1mhPRIS11amSwdKf4OFZlt2ibj7XJwu05kVWt4S_L-ZNuD" target="_blank" rel="noreferrer">TBS Crossfire Nano RX</a></p></li><li><p>Power: 3S Lipo Battery</p></li><li><p>GNSS: <a href="./../gps_compass/rtk_gps_holybro_h-rtk-f9p">Holybro RTK F9P GPS</a></p></li><li><p>I2C Splitter</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This part is only necessary if your flight controller has only one I2C port (we need one for the motor driver board and one for the compass in the GNSS module). Many boards will have a dedicated GPS port (which often includes an I2C port) and one or more separate I2C ports for additional peripherals.</p></div></li><li><p>LTE Dongle: Used to establish a data link between the vehicle and the ground control station.</p></li></ul><h2 id="wiring-and-assembly" tabindex="-1">Wiring and Assembly <a class="header-anchor" href="#wiring-and-assembly" aria-label="Permalink to &quot;Wiring and Assembly&quot;">​</a></h2><p>The following images shows the wiring of the various components of this build. The connections from the motors to the motor controller board are not shown.</p><p><img src="'+a+'" alt="Hiwonder Wiring"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This image only serves as an example for the wiring process, with your hardware this can look very different. Check the documentation of your parts to ensure that you connect to correct pins.</p></div><p>To assemble your rover connect the motors to the chassis using the supplied screws, mount the wheels to the motor shafts (there are 2 different types of mecanum wheels, make sure you mount them to the correct motor!) and securely attach your hardware.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For the initial build you might attach components using double sided tape. For a longer term solution we highly recommend 3d printing mounts that you attach to the chassis using the mounting points.</p></div><h2 id="building-the-firmware" tabindex="-1">Building the Firmware <a class="header-anchor" href="#building-the-firmware" aria-label="Permalink to &quot;Building the Firmware&quot;">​</a></h2><p>This frame works with the usual Rover firmware variants on most flight controllers. You can use either prebuilt versions or build the firmware yourself (see <a href="./../config_rover/#flashing-the-rover-build">Flashing the Rover Build</a> and <a href="./../config_rover/#building-rover">Building Rover</a> in <em>Rover Configuration/Tuning</em>).</p><p>A few boards may omit the <a href="./../modules/modules_driver#hiwonder-emm"><code>hiwonder_emm</code> driver</a> for the <a href="./../peripherals/hiwonder_emm">Hiwonder 4-Channel Encoder Motor Module</a> used by this vehicle. If your board does not ship with it you will need a custom build — see <a href="./../peripherals/hiwonder_emm#building-the-firmware">Hiwonder 4-Channel Encoder Motor Module &gt; Building the Firmware</a> for instructions.</p><h2 id="px4-configuration" tabindex="-1">PX4 Configuration <a class="header-anchor" href="#px4-configuration" aria-label="Permalink to &quot;PX4 Configuration&quot;">​</a></h2><p>Use <em>QGroundControl</em> for rover configuration:</p><ol><li><a href="./../config_rover/#flashing-the-rover-build">Flash the rover build</a> onto your flight controller with the following adjustments:</li><li>In the <a href="./../config/">Basic Configuration</a> section, select the <a href="./../config/airframe">Airframe</a> tab.</li><li>Choose <strong>Hiwonder Mecanum</strong> under the <strong>Rover</strong> category (Alternatively you can set the parameter <code>SYS_AUTOSTART</code> to <code>52001</code>).</li></ol><p>Then configure the actuators:</p><ol><li><p>Navigate to <a href="./../config/actuators">Actuators Configuration &amp; Testing</a> in QGroundControl.</p></li><li><p>Select the Hiwonder EMM driver from the list of <em>Actuator Outputs</em>.</p><p>Assign the channels to the corresponding motor. The channels are noted on the motor controller board (alternatively randomly assign the channels and use the actuator testing tab to find the correct assignments). Now ensure that the motors are all spinning in the same direction. If that is not the case check the <code>Rev Range</code> box on the ones that are spinning in the opposite direction.</p><p><img src="'+i+'" alt="Motor Setup"></p></li><li><p>Arm the rover in <a href="./../flight_modes_rover/manual#manual-mode">Manual Mode</a> and use the trottle stick to drive forwards. If the rover drives backwards instead, invert the <code>Rev Range</code> checkboxes on <strong>all</strong> motors.</p></li></ol><p>You have now successfully setup your rover and can start testing all <a href="./../flight_modes_rover/">driving modes</a> PX4 has to offer!</p>',22))])}const C=n(m,[["render",u]]);export{S as __pageData,C as default};
